// "the viewport is set to {string} by {string}" is defined once in staff.steps.ts and
// reused here.

import { GivenR as Given, WhenR as When, ThenR as Then } from './support/td-resolve';
import { expect } from '@playwright/test';
import { ScenarioContext } from '../../Framework/src/utils/ScenarioContext';
import { ConfigurationManager } from '../../Framework/src/config/ConfigurationManager';

// ==================== Given ====================

Given('I note the current Bucks tag count on the Guide dashboard', async function (this: ScenarioContext) {
  await this.guidePortalPage.navigateToGuideDashboard();
  this.testData.bucksCountBefore = await this.guidePortalPage.bucksTagCountElement.textContent();
});

// ==================== When ====================

When('I navigate to the invoice\\/billing view for booking {string}', async function (this: ScenarioContext, bookingId: string) {
  await this.guidePortalPage.navigateToBookingDetail(bookingId);
});

When('I navigate to the Booking Detail screen for {string}', async function (this: ScenarioContext, bookingId: string) {
  await this.guidePortalPage.navigateToBookingDetail(bookingId);
});

When('I navigate to the Harvest Log screen for booking {string}', async function (this: ScenarioContext, _bookingId: string) {
  await this.guidePortalPage.navigateToHarvestLogScreen();
});

When(
  'I capture network responses while navigating to the invoice\\/booking\\/harvest screens for {string}',
  async function (this: ScenarioContext, bookingId: string) {
    this.testData.capturedPayloads = await this.guidePortalPage.captureNetworkResponsesDuringNavigation(/invoice|booking|harvest/i, async () => {
      await this.guidePortalPage.navigateToBookingDetail(bookingId);
      await this.guidePortalPage.navigateToHarvestLogScreen();
    });
  },
);

When('I directly navigate to the Generate Invoice page URL', async function (this: ScenarioContext) {
  await this.guidePortalPage.navigateDirectlyToGenerateInvoiceUrl(ConfigurationManager.config().baseUrl);
});

When('I navigate to the Guide dashboard', async function (this: ScenarioContext) {
  await this.guidePortalPage.navigateToGuideDashboard();
});

When('a new Whitetail Deer Buck harvest is logged', async function (this: ScenarioContext) {
  await this.harvestPage.navigateToHarvestLogList();
  await this.harvestPage.createHarvestLog({
    ranchName: this.testData.ranchName as string,
    animalName: 'Whitetail Deer',
    categoryName: 'Deer',
    age: '3',
    sex: 'Male',
  });
});

When('I return to the Guide dashboard', async function (this: ScenarioContext) {
  await this.guidePortalPage.navigateToGuideDashboard();
});

When('I run the pricing-absence check across each supported browser', async function (this: ScenarioContext) {
  // Cross-browser matrix is driven by the Cucumber/Playwright browser project configuration.
  await this.guidePortalPage.navigateToGuideDashboard();
});

When('I tab through the Guide dashboard elements', async function (this: ScenarioContext) {
  for (let i = 0; i < 6; i += 1) {
    await this.page.keyboard.press('Tab');
  }
});

// ==================== Then ====================

Then('no pricing fields should be visible on the current screen', async function (this: ScenarioContext) {
  await this.guidePortalPage.assertNoPricingFieldVisible();
});

Then('no pricing field should appear in any captured network response payload', async function (this: ScenarioContext) {
  const payloads = (this.testData.capturedPayloads as string[]) ?? [];
  this.guidePortalPage.assertNoPricingKeywordInPayloads(payloads);
});

Then('the Guide should be blocked\\/redirected or no pricing data should be exposed', async function (this: ScenarioContext) {
  await this.guidePortalPage.assertBlockedOrNoPricingOnDirectNav();
});

Then(
  'the Bucks tag count should display {string} allocated and {string} remaining',
  async function (this: ScenarioContext, allocated: string, remaining: string) {
    await this.guidePortalPage.assertTagCountValue(this.guidePortalPage.bucksTagCountElement, remaining);
  },
);

Then(
  'the Does tag count should display {string} allocated and {string} remaining',
  async function (this: ScenarioContext, allocated: string, remaining: string) {
    await this.guidePortalPage.assertTagCountValue(this.guidePortalPage.doesTagCountElement, remaining);
  },
);

Then('the Bucks and Does tag counts should be distinct elements', async function (this: ScenarioContext) {
  await this.guidePortalPage.assertBucksAndDoesCountsDistinct();
});

Then('the Bucks tag count should have decreased by exactly one consumed tag', async function (this: ScenarioContext) {
  const before = Number((this.testData.bucksCountBefore as string)?.match(/\d+/)?.[0] ?? '0');
  const afterText = await this.guidePortalPage.bucksTagCountElement.textContent();
  const after = Number(afterText?.match(/\d+/)?.[0] ?? '0');
  expect(before - after).toBe(1);
});

Then('the bookings list should render with its expected column headers and at least one row', async function (this: ScenarioContext) {
  await this.guidePortalPage.assertGuideBookingsListStructureVisible();
});

Then('the dashboard should render usably with no horizontal overflow and readable tag counts', async function (this: ScenarioContext) {
  const hasOverflow = await this.page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth);
  expect(hasOverflow).toBeFalsy();
});

Then('the dashboard should render with no overlapping content', async function (this: ScenarioContext) {
  await this.guidePortalPage.assertGuideBookingsListStructureVisible();
});

Then('no pricing fields should be visible on the current screen in any supported browser', async function (this: ScenarioContext) {
  await this.guidePortalPage.assertNoPricingFieldVisible();
});

Then(
  'every interactive element should receive keyboard focus in logical order with a visible focus indicator',
  async function (this: ScenarioContext) {
    const focused = await this.page.evaluate(() => document.activeElement?.tagName);
    expect(focused).toBeTruthy();
  },
);

Then(
  'the bookings list column headers should use semantic header markup or an equivalent accessible name',
  async function (this: ScenarioContext) {
    await expect(this.guidePortalPage.guideBookingsTableColumnHeaders.first()).toBeVisible();
  },
);
